"""Post-exit manifest and basic arithmetic checks for scripts 158/159."""
from pathlib import Path
from fractions import Fraction as F
from itertools import product
import argparse,hashlib,json,math,sys
CHECK=(1,10,50,100,200,500,1000,1500,2000);MATCH={1,500,1000,1500,2000}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def need(v,msg):
 if not v:raise ValueError(msg)
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--training',required=True,type=Path);ap.add_argument('--certificates',required=True,type=Path);ap.add_argument('--grid',required=True,type=Path);ap.add_argument('--replay',required=True,type=Path);a=ap.parse_args();ts=json.loads((a.training/'summary.json').read_text());fp=a.training/'frozen_networks.json';lp=a.training/'training_log.json';need(sha(fp)==ts['fixture_sha256'] and sha(lp)==ts['training_log_sha256'],'training hashes');nets=json.loads(fp.read_text())['networks'];labels={n['label'] for n in nets};nmap={n['label']:n for n in nets};logs={r['label']:r for r in json.loads(lp.read_text())};need(len(labels)==len(nets)==12 and set(logs)==labels,'training manifest');cs=json.loads((a.certificates/'summary.json').read_text());refp=a.certificates/'references.json';need(sha(refp)==cs['references_sha256'] and cs['fixture_sha256']==ts['fixture_sha256'],'reference hash');refs={q['network']:q for q in json.loads(refp.read_text())};need(set(refs)==labels,'ref labels')
 s=json.loads((a.grid/'summary.json').read_text());rp=a.grid/'records.json';need(sha(rp)==s['records_sha256'] and s['fixture_sha256']==ts['fixture_sha256'] and s['training_log_sha256']==ts['training_log_sha256'] and sha(Path(__file__).with_name('158_sine_training_diagnostics_20261102.py'))==s['script_sha256'],'grid hashes');rows=json.loads(rp.read_text());need(len(rows)==s['records']==s['expected']==12 and {r['network'] for r in rows}==labels,'grid keys')
 for r in rows:
  n=nmap[r['network']];need((r['frequency'],r['depth'],r['seed'])==(n['frequency'],n['depth'],n['seed']) and r['grid_points']==10001,'grid metadata');need(all(math.isfinite(r[x]) for x in ('network_N_grid_min','network_N_grid_max','network_N_grid_range','v_grid_absmax','error_grid_absmax','best_constant_c','best_constant_collocation_mse','final_collocation_loss','difference_loss_to_constant')),'nonfinite');need(r['network_N_grid_min']<=r['network_N_grid_max'] and math.isclose(r['network_N_grid_range'],r['network_N_grid_max']-r['network_N_grid_min'],rel_tol=1e-12,abs_tol=1e-14),'grid range');need(r['final_collocation_loss']==logs[r['network']]['final_collocation_loss'] and math.isclose(r['difference_loss_to_constant'],r['final_collocation_loss']-r['best_constant_collocation_mse'],rel_tol=1e-10,abs_tol=1e-10),'loss');k=n['frequency'];values=[(k*math.pi)**2*math.sin(k*math.pi*i/65) for i in range(1,65)];mean=math.fsum(values)/64;constant=math.fsum((v-mean)**2 for v in values)/64;need(math.isclose(r['best_constant_c'],mean/2,rel_tol=1e-12,abs_tol=1e-12) and math.isclose(r['best_constant_collocation_mse'],constant,rel_tol=1e-12,abs_tol=1e-10),'constant model');need(r['error_grid_absmax']<=float(F(refs[r['network']]['upper']))+1e-10,'sample exceeds reference upper')
 s2=json.loads((a.replay/'summary.json').read_text());rp=a.replay/'records.json';need(sha(rp)==s2['records_sha256'] and s2['training_log_sha256']==ts['training_log_sha256'] and s2['training_config_sha256']==ts['config_sha256'] and sha(Path(__file__).with_name('159_sine_adam_diagnostics_20261102.py'))==s2['script_sha256'],'replay hashes');rows2=json.loads(rp.read_text());keys=[(r['depth'],r['seed'],r['step_before_update']) for r in rows2];expected=set(product((1,2),(501,502),CHECK));need(len(rows2)==len(set(keys))==s2['expected']==s2['records']==len(expected) and set(keys)==expected,'replay manifest')
 for r in rows2:
  need(r['network']==f"sine_k5_depth{r['depth']}_seed{r['seed']}" and len(r['linear_layer_gradient_norms'])==r['depth']+1 and len(r['hidden_layer_samples'])==r['depth'],'replay metadata');need(r['network_N_min']<=r['network_N_max'] and math.isclose(r['network_N_range'],r['network_N_max']-r['network_N_min'],rel_tol=1e-12,abs_tol=1e-14),'replay range');need(all(math.isfinite(g) and g>=0 for g in r['linear_layer_gradient_norms']),'gradients');need(all(0<=v['fraction_abs_z_ge_10']<=v['fraction_abs_z_ge_5']<=1 and 0<=v['mean_tanh_slope']<=1 for v in r['hidden_layer_samples']),'hidden stats')
  if r['step_before_update'] in MATCH:
   original={x['step']:x['loss_before_update'] for x in logs[r['network']]['adam_history']}[r['step_before_update']];need(r['prior_loss_matches']==math.isclose(r['loss_before_update'],original,rel_tol=1e-12,abs_tol=1e-12) and r['prior_loss_matches'],'replay mismatch')
  else:need(r['prior_loss_matches'] is None,'unexpected replay flag')
 need(s2['prior_loss_comparisons']==20 and s2['prior_loss_matches']==sum(r['prior_loss_matches'] is True for r in rows2)==20,'replay totals');print(json.dumps({'ok':True,'grid_records':len(rows),'replay_records':len(rows2),'loss_checkpoints_match':s2['prior_loss_matches'],'scope':'record and arithmetic readback; sampling is not continuous proof'}));return 0
if __name__=='__main__':
 try:sys.exit(main())
 except (OSError,ValueError,KeyError,TypeError,ZeroDivisionError) as e:print(json.dumps({'ok':False,'error':str(e)}));sys.exit(1)
